SELECT id, order_id, carrier, delivered_date, cost, status, LEAD(cost) OVER (PARTITION BY status, order_id ORDER BY shipped_date, id) AS next_cost, LAG(cost) OVER (PARTITION BY status, order_id ORDER BY shipped_date, id) AS prev_cost, ROW_NUMBER() OVER (PARTITION BY status, order_id ORDER BY shipped_date, id) AS row_seq, ROUND(cost / SUM(cost) OVER (PARTITION BY order_id), 4) AS cost_share FROM shipments;
